<?php
require_once '../config/session.php'; require_once '../config/config.php';
if (empty($_SESSION['user_id']) || ($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: ../auth/login.php'); exit; }
$rows = $conn->query('SELECT r.*,s.full_name,e.title FROM results r JOIN students s ON s.id=r.student_id JOIN exams e ON e.id=r.exam_id ORDER BY r.created_at DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
function result_escape($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
$page_title='Results | ExamSphere'; $page_css='admin-subjects.css'; include 'includes/header.php';
?>
<div class="dashboard-wrapper"><?php include 'includes/sidebar.php'; ?><div class="main-content"><?php include 'includes/navbar.php'; ?>
<main class="dashboard-content subject-page"><div class="subject-page-heading"><div><span><i class="fa-solid fa-chart-column"></i> EVALUATION CENTER</span><h1>Exam Results</h1><p>Review every automatically evaluated student examination attempt.</p></div></div>
<section class="subject-stat-row"><article><i class="fa-solid fa-file-circle-check"></i><span><small>Evaluated results</small><b><?=count($rows)?></b></span></article><article><i class="fa-solid fa-user-graduate"></i><span><small>Students assessed</small><b><?=count(array_unique(array_column($rows,'student_id')))?></b></span></article><article><i class="fa-solid fa-award"></i><span><small>Passed attempts</small><b><?=count(array_filter($rows,fn($row)=>$row['result_status']==='Pass'))?></b></span></article></section>
<section class="subject-list-card"><div class="subject-card-heading list-heading"><div><span class="mini-kicker">HISTORY</span><h2>All result records</h2></div><div class="subject-search"><i class="fa-solid fa-magnifying-glass"></i><input id="resultSearch" type="search" placeholder="Search results"></div></div><div class="subject-table-wrap"><table class="subject-table" id="resultTable"><thead><tr><th>Student</th><th>Exam</th><th>Marks</th><th>Percentage</th><th>Outcome</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td data-label="Student"><b><?=result_escape($row['full_name'])?></b></td><td data-label="Exam"><b><?=result_escape($row['title'])?></b></td><td data-label="Marks"><span class="count-pill"><?=result_escape($row['obtained_marks'])?> / <?=result_escape($row['total_marks'])?></span></td><td data-label="Percentage"><b><?=result_escape($row['percentage'])?>%</b></td><td data-label="Outcome"><span class="status-pill <?=$row['result_status']==='Pass'?'active':'inactive'?>"><?=result_escape($row['result_status'])?></span></td><td data-label="Date"><?=date('d M Y',strtotime($row['created_at']))?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr class="subject-empty"><td colspan="6"><i class="fa-solid fa-chart-line"></i>No results are available yet.</td></tr><?php endif;?></tbody></table></div></section></main></div></div>
